def count_nums(arr):
    count = 0
    for num in arr:
        s = str(num)
        if s[0] == '-':
            digits = [int(d) for d in s[1:]]
            total = -digits[0] + sum(digits[1:]) if digits else 0
        else:
            total = sum(int(d) for d in s)
        if total > 0:
            count += 1
    return count
